#!/bin/bash

HF=/opt/homebrew/lib/node_modules/@higgsfield/cli/vendor/hf
STYLE="Stick figure illustration rich vibrant colours. Thick uneven black outlines. Wobbly hand drawn lines. Stick figure humans with round heads dot eyes simple line bodies. Rich vibrant colourful backgrounds. Space scenes deep dark blue and purple backgrounds packed with bright white stars glowing suns blue and green Earth orange planets silver rockets. Handwritten labels and red arrows for emphasis. Objects simple but clearly recognisable. Lots of colour bright yellows electric blues vivid purples warm oranges glowing greens. Every scene feels alive with colour and energy. No realistic shading no 3D no white backgrounds. 16:9 aspect ratio."

mkdir -p output_hestia

gen() {
  local num=$1
  local prompt=$2
  local attempts=0
  echo "Generating image $num..."
  local job_id=""
  until [[ -n "$job_id" ]]; do
    job_id=$($HF generate create nano_banana_2 --prompt "${STYLE} ${prompt}" --json 2>/dev/null | tr -d '[]" \n')
    if [[ -z "$job_id" ]]; then
      attempts=$((attempts + 1))
      if [ $attempts -ge 3 ]; then
        echo "FAILED image $num after 3 attempts"
        return
      fi
      echo "Retrying image $num (attempt $attempts)..."
      sleep 5
    fi
  done
  echo "Waiting for image $num..."
  $HF generate wait "$job_id" > "output_hestia/image_${num}.txt" 2>&1
  echo "Done $num"
}

BATCH_SIZE=10
pids=()

run_batch() {
  for pid in "${pids[@]}"; do
    wait "$pid"
  done
  pids=()
}

